package com.fakelegacy.customer;

import java.util.HashMap;
import java.util.Map;

/** Home-made singleton, deliberately not a Spring bean. */
public class TierCache {

    private static final long TTL_MILLIS = 10 * 60 * 1000L;
    private static TierCache instance;

    private final Map<Long, Object[]> entries = new HashMap<>();

    private TierCache() {
    }

    public static synchronized TierCache getInstance() {
        if (instance == null) {
            instance = new TierCache();
        }
        return instance;
    }

    public synchronized String get(Long customerId) {
        Object[] e = entries.get(customerId);
        if (e == null) {
            return null;
        }
        if (System.currentTimeMillis() > (Long) e[1]) {
            entries.remove(customerId);
            return null;
        }
        return (String) e[0];
    }

    public synchronized void put(Long customerId, String tier) {
        entries.put(customerId, new Object[] { tier, System.currentTimeMillis() + TTL_MILLIS });
    }

    public synchronized void invalidate(Long customerId) {
        entries.remove(customerId);
    }
}
